/** Extract outward code from full postcode (e.g. "SW11 1AA" → "SW11") */
export function extractOutwardCode(postcode: string): string {
  // Handle multiple postcodes separated by semicolons (e.g. "SW11 1;SW11 6")
  const first = postcode.split(";")[0].trim();
  const pc = first.toUpperCase().replace(/\s/g, "");
  // Inward code is always last 3 chars (digit + 2 letters), rest is outward
  if (pc.length >= 4) {
    return pc.slice(0, -3);
  }
  return pc;
}

/** Look up area/town/location by outward code */
export function lookupOutwardCode(outward: string): OutwardCodeInfo | null {
  return OUTWARD_CODES[outward.toUpperCase()] || null;
}

/** Look up by full postcode */
export function lookupPostcode(postcode: string): OutwardCodeInfo | null {
  return lookupOutwardCode(extractOutwardCode(postcode));
}

/** Find nearest outward code by coordinates (squared distance for comparison) */
export function findNearestOutwardCode(lat: number, lon: number): (OutwardCodeInfo & { outward: string }) | null {
  let best: (OutwardCodeInfo & { outward: string; dist: number }) | null = null;
  for (const [outward, info] of Object.entries(OUTWARD_CODES)) {
    const dlat = info.lat - lat;
    const dlon = info.lon - lon;
    const dist = dlat * dlat + dlon * dlon;
    if (!best || dist < best.dist) {
      best = { ...info, outward, dist };
    }
  }
  return best;
}
